import React from 'react'
import {type TextStyle} from 'react-native'
import {repSocialEmbedded} from '@fluxion-labs/rep-social'
import {
  AppBskyRichtextFacet,
  RichText as RichTextAPI,
} from '@reprun/atproto-api'

import {toShortUrl} from '#/lib/strings/url-helpers'
import {atoms as a, flatten, type TextStyleProp} from '#/alf'
import {isOnlyEmoji} from '#/alf/typography'
import {InlineLinkText, type LinkProps} from '#/components/Link'
import {ProfileHoverCard} from '#/components/ProfileHoverCard'
import {RichTextTag} from '#/components/RichTextTag'
import {Text, type TextProps} from '#/components/Typography'

const WORD_WRAP = {wordWrap: 1}

export type RichTextProps = TextStyleProp &
  Pick<TextProps, 'selectable' | 'onLayout' | 'onTextLayout'> & {
    value: RichTextAPI | string
    testID?: string
    numberOfLines?: number
    disableLinks?: boolean
    enableTags?: boolean
    authorHandle?: string
    onLinkPress?: LinkProps['onPress']
    interactiveStyle?: TextStyle
    emojiMultiplier?: number
    shouldProxyLinks?: boolean
  }

export function RichText({
  testID,
  value,
  style,
  numberOfLines,
  disableLinks,
  selectable,
  enableTags = false,
  authorHandle,
  onLinkPress,
  interactiveStyle,
  emojiMultiplier = 1.85,
  onLayout,
  onTextLayout,
  shouldProxyLinks,
}: RichTextProps) {
  const flattenedStyle = flatten(style)
  const plainStyles = [a.leading_snug, flattenedStyle]
  const interactiveStyles = [
    a.leading_snug,
    flatten(interactiveStyle),
    flattenedStyle,
  ]

  // 2) Trim off the last "\n\n… - Get RepSky" and its facets
  const trimmedRichText = React.useMemo(() => {
    const richText =
      value instanceof RichTextAPI ? value : new RichTextAPI({text: value})
    let {text, facets} = richText

    // find the last double-newline
    const sep = '\n\n'
    const idx = text.lastIndexOf(sep)

    if (
      idx !== -1 &&
      (text.slice(idx + sep.length).endsWith(' - Get RepSky') ||
        text.slice(idx + sep.length).endsWith(' - From rsky.ai'))
    ) {
      // 2a) cut the text
      text = text.slice(0, idx)

      // 2b) drop only link/mention facets that live beyond the cut,
      // but keep any other facet types in place
      const TRIM_TYPES = new Set(['app.bsky.richtext.facet#link'])

      facets = facets?.filter(f => {
        // if it’s one of the types we want to trim, enforce the byteEnd check
        if (f.$type && TRIM_TYPES.has(f.$type)) {
          return f.index.byteEnd <= text.length
        }
        // otherwise, keep it no matter what
        return true
      })
    }

    // 3) return a brand-new RichTextAPI instance
    const rt = new RichTextAPI({text})
    // if you need to preserve the precomputed facets:
    // @ts-ignore
    rt.facets = facets

    return rt
  }, [value])

  // from here on, use `trimmedRichText.text` and `trimmedRichText.segments()`
  // exactly as before, and you’ll never see that final “localhost…” slice.

  const {text, facets} = trimmedRichText

  if (!facets?.length) {
    if (isOnlyEmoji(text)) {
      const fontSize =
        (flattenedStyle.fontSize ?? a.text_sm.fontSize) * emojiMultiplier
      return (
        <Text
          emoji
          selectable={selectable}
          testID={testID}
          style={[plainStyles, {fontSize}]}
          onLayout={onLayout}
          onTextLayout={onTextLayout}
          // @ts-ignore web only -prf
          dataSet={WORD_WRAP}>
          {text}
        </Text>
      )
    }
    return (
      <Text
        emoji
        selectable={selectable}
        testID={testID}
        style={plainStyles}
        numberOfLines={numberOfLines}
        onLayout={onLayout}
        onTextLayout={onTextLayout}
        // @ts-ignore web only -prf
        dataSet={WORD_WRAP}>
        {text}
      </Text>
    )
  }

  const els = []
  let key = 0
  // N.B. must access segments via `richText.segments`, not via destructuring
  for (const segment of trimmedRichText.segments()) {
    const link = segment.link
    const mention = segment.mention
    const tag = segment.tag
    if (
      mention &&
      AppBskyRichtextFacet.validateMention(mention).success &&
      !disableLinks
    ) {
      els.push(
        <ProfileHoverCard key={key} inline did={mention.did}>
          <InlineLinkText
            selectable={selectable}
            to={`/profile/${mention.did}`}
            style={interactiveStyles}
            // @ts-ignore TODO
            dataSet={WORD_WRAP}
            shouldProxy={shouldProxyLinks}
            onPress={onLinkPress}>
            {segment.text}
          </InlineLinkText>
        </ProfileHoverCard>,
      )
    } else if (link && AppBskyRichtextFacet.validateLink(link).success) {
      if (disableLinks) {
        els.push(toShortUrl(segment.text))
      } else {
        els.push(
          <InlineLinkText
            selectable={selectable}
            key={key}
            to={link.uri}
            style={interactiveStyles}
            // @ts-ignore TODO
            dataSet={WORD_WRAP}
            shareOnLongPress
            shouldProxy={shouldProxyLinks}
            onPress={() => {
              if (
                repSocialEmbedded.isMobileEmbedded ||
                repSocialEmbedded.isMobileIOSEmbedded
              ) {
                window.location.href = link.uri
                return
              }
              onLinkPress
            }}
            emoji>
            {toShortUrl(segment.text)}
          </InlineLinkText>,
        )
      }
    } else if (
      !disableLinks &&
      enableTags &&
      tag &&
      AppBskyRichtextFacet.validateTag(tag).success
    ) {
      els.push(
        <RichTextTag
          key={key}
          display={segment.text}
          tag={tag.tag}
          textStyle={interactiveStyles}
          authorHandle={authorHandle}
        />,
      )
    } else {
      els.push(segment.text)
    }
    key++
  }

  return (
    <Text
      emoji
      selectable={selectable}
      testID={testID}
      style={plainStyles}
      numberOfLines={numberOfLines}
      onLayout={onLayout}
      onTextLayout={onTextLayout}
      // @ts-ignore web only -prf
      dataSet={WORD_WRAP}>
      {els}
    </Text>
  )
}
