import 'tippy.js/dist/tippy.css'

import React, {
  type ReactElement,
  type RefObject,
  useEffect,
  useRef,
} from 'react'
import tippy, {type Instance, type Props as TippyProps} from 'tippy.js'

import {useColorModeTheme} from '#/alf/util/useColorModeTheme'

export interface TooltipProps extends Partial<TippyProps> {
  /** The tooltip text to show */
  content: string
  /** Exactly one React element that accepts a `ref` to an HTMLElement */
  children: ReactElement<
    React.HTMLAttributes<HTMLElement> & React.RefAttributes<HTMLElement>
  >
}

export function Tooltip({
  content,
  placement = 'bottom',
  delay = [100, 0],
  theme,
  children,
  ...rest
}: TooltipProps) {
  const t = useColorModeTheme()

  const ref = useRef<HTMLElement>(null)

  useEffect(() => {
    let instance: Instance | null = null
    if (ref.current && content) {
      instance = tippy(ref.current, {
        content,
        placement,
        delay,
        theme: theme ?? t ?? 'light',
        ...rest,
      })
    }
    return () => instance?.destroy()
  }, [content, placement, delay, theme, rest, t])

  // Clone the single child and inject only the ref
  return React.cloneElement(children, {ref} as {ref: RefObject<HTMLElement>})
}
