import {useMemo} from 'react'
import {SafeAreaView, View} from 'react-native'
import {msg, Trans} from '@lingui/macro'
import {useLingui} from '@lingui/react'

import {type UserInfo} from '#/lib/api/user'
import {usePalette} from '#/lib/hooks/usePalette'
import {s} from '#/lib/styles'
import {isAndroid} from '#/platform/detection'
import {useModalControls} from '#/state/modals'
import {useProfileQuery} from '#/state/queries/profile'
import {atoms as a} from '#/alf'
import {Button, ButtonIcon, ButtonText} from '#/components/Button'
import {GoldBadgeIcon, SilverBadgeIcon} from '#/components/icons/Badge'
import {TimesLarge_Stroke2_Corner0_Rounded as X} from '#/components/icons/Times'
import {Text} from '../util/text/Text'
import {UserAvatar} from '../util/UserAvatar'
import {ScrollView} from './util'

export const snapPoints = isAndroid ? ['90%'] : ['55%']

export function Component({data}: {data: UserInfo}) {
  const pal = usePalette('default')

  const {_} = useLingui()
  const {closeModal} = useModalControls()
  const {handle: did, role} = data

  const info = useMemo(() => {
    if (role === 'Gold') {
      return {
        color: '#FFD700',
        subtitle: 'You’re now a Gold User!',
        Icon: GoldBadgeIcon,
      }
    }
    return {
      color: '#727272',
      subtitle: 'You’re now a Silver User!',
      Icon: SilverBadgeIcon,
    }
  }, [role])

  const {data: currentProfile} = useProfileQuery({did})

  return (
    <SafeAreaView style={[s.flex1, {width: '100%', maxWidth: 432}]}>
      <ScrollView style={[pal.view]} keyboardShouldPersistTaps="handled">
        <View
          style={[
            pal.view,
            a.flex,
            a.flex_row,
            a.align_center,
            a.justify_between,
            a.mb_xl,
          ]}>
          <Text type="title-lg" style={[pal.text]}>
            <Trans>Verification Complete</Trans>
          </Text>
          <Button
            label={_(msg`Hide verification complete`)}
            size="small"
            variant="ghost"
            color="secondary"
            shape="round"
            onPress={() => closeModal()}>
            <ButtonIcon icon={X} />
          </Button>
        </View>
        <View style={[a.gap_sm, a.mb_2xl, a.relative]}>
          <UserAvatar
            avatar={currentProfile?.avatar}
            size={50}
            style={[
              a.border,
              a.rounded_full,
              {
                borderColor: info.color,
                borderWidth: 2,
                borderRadius: '100%',
                boxSizing: 'content-box',
              },
            ]}
            type={'user'}
          />
          <info.Icon
            style={{
              position: 'absolute',
              bottom: 1,
              left: 28,
              width: 24,
              height: 24,
            }}
          />
        </View>
        <View style={[a.flex, a.gap_sm, a.mb_2xl]}>
          <Text style={[pal.text, a.text_lg, a.font_bold]}>
            {info.subtitle}
          </Text>
          <Text style={[pal.text, a.text_sm, a.font_normal, {opacity: 0.7}]}>
            Silver User status unlocked — post up to 10 times per day and enjoy
            your trusted profile badge.
          </Text>
        </View>

        <View style={[a.flex, a.flex_row, a.justify_end, a.gap_sm]}>
          <Button
            label={_(msg`Explore`)}
            onPress={closeModal}
            size="small"
            variant="solid"
            color="primary"
            style={[a.mt_sm, {width: 120}]}>
            <ButtonText>
              <Trans context="action">Explore</Trans>
            </ButtonText>
          </Button>
        </View>
      </ScrollView>
    </SafeAreaView>
  )
}
