export interface CreateRoomPayload {
  roomId: string
  invitedUserId: string
  callType: CallType
}

export interface CallInvitationData {
  fromUserId: string
  toUserId: string
  roomId: string
}

export enum CallType {
  AUDIO = 'AUDIO',
  VIDEO = 'VIDEO',
}

export enum RoomEvent {
  // Core
  CREATE_ROOM = 'CREATE_ROOM',
  ROOM_CREATED = 'ROOM_CREATED',
  JOIN_ROOM = 'JOIN_ROOM',
  LEAVE_ROOM = 'LEAVE_ROOM',

  // Invitation
  CALL_INVITATION = 'CALL_INVITATION',
  REJECT_CALL = 'REJECT_CALL',
  CANCEL_CALL = 'CANCEL_CALL',

  // Status
  USER_JOINED_ROOM = 'USER_JOINED_ROOM',
  USER_LEAVE_ROOM = 'USER_LEAVE_ROOM',
  USER_DISCONNECTED = 'USER_DISCONNECTED',
  CALL_CANCELLED = 'CALL_CANCELLED',
  CALL_REJECTED = 'CALL_REJECTED',
  CALL_TIMEOUT = 'CALL_TIMEOUT',
  ROOM_ENDED = 'ROOM_ENDED',

  // Errors
  ROOM_NOT_FOUND = 'ROOM_NOT_FOUND',
  USER_ALREADY_IN_ROOM = 'USER_ALREADY_IN_ROOM',
  YOU_ALREADY_IN_ROOM = 'YOU_ALREADY_IN_ROOM',
  USER_NOT_ONLINE = 'USER_NOT_ONLINE',
  USER_UNAVAILABLE = 'USER_UNAVAILABLE',
}
