import {SafeAreaView, View} from 'react-native'
import {msg, Trans} from '@lingui/macro'
import {useLingui} from '@lingui/react'
import {useNavigation} from '@react-navigation/native'

import {type PaymentInfoItem} from '#/lib/api/gold-member'
import {usePalette} from '#/lib/hooks/usePalette'
import {type NavigationProp} from '#/lib/routes/types'
import {formatDateTime} from '#/lib/sharing'
import {s} from '#/lib/styles'
import {isAndroid} from '#/platform/detection'
import {useModalControls} from '#/state/modals'
import {useProfileQuery} from '#/state/queries/profile'
import {useSession} from '#/state/session'
import {atoms as a, useTheme} from '#/alf'
import {Button, ButtonIcon, ButtonText} from '#/components/Button'
import {GoldBadgeIcon} from '#/components/icons/Badge'
import {TimesLarge_Stroke2_Corner0_Rounded as X} from '#/components/icons/Times'
import {Text} from '../util/text/Text'
import {UserAvatar} from '../util/UserAvatar'
import {ScrollView} from './util'

export const snapPoints = isAndroid ? ['90%'] : ['55%']

export function Component({data}: {data: PaymentInfoItem}) {
  const pal = usePalette('default')
  const t = useTheme()
  const {_} = useLingui()
  const {closeModal} = useModalControls()
  const {currentAccount} = useSession()
  const navigation = useNavigation<NavigationProp>()
  const {data: currentProfile} = useProfileQuery({did: currentAccount?.did})

  return (
    <SafeAreaView style={[s.flex1, {width: '100%', maxWidth: 432}]}>
      <ScrollView style={[pal.view]} keyboardShouldPersistTaps="handled">
        <View
          style={[
            pal.view,
            a.flex,
            a.flex_row,
            a.align_center,
            a.justify_between,
            a.mb_xl,
          ]}>
          <Text type="title-lg" style={[pal.text]}>
            <Trans>Subscribed</Trans>
          </Text>
          <Button
            label={_(msg`Hide verification complete`)}
            size="small"
            variant="ghost"
            color="secondary"
            shape="round"
            onPress={() => closeModal()}>
            <ButtonIcon icon={X} />
          </Button>
        </View>
        <View style={[a.gap_sm, a.mb_2xl, a.relative]}>
          <UserAvatar
            avatar={currentProfile?.avatar}
            size={50}
            style={[
              a.border,
              a.rounded_full,
              {
                borderColor: '#ECC78F',
                borderWidth: 2,
                borderRadius: '100%',
                boxSizing: 'content-box',
              },
            ]}
            type={'user'}
          />
          <GoldBadgeIcon
            style={{
              position: 'absolute',
              bottom: 1,
              left: 28,
              width: 24,
              height: 24,
            }}
          />
        </View>
        <View style={[a.flex, a.gap_sm, a.mb_2xl]}>
          <Text style={[pal.text, a.text_lg, a.font_bold]}>
            You’re now a Gold Member!
          </Text>
          <Text style={[pal.text, a.text_md, a.font_normal, {opacity: 0.5}]}>
            Gold Member status has been unlocked — enjoy unlimited posts and
            exclusive features.
          </Text>
        </View>

        <View
          style={[
            a.flex,
            a.gap_sm,
            a.mb_2xl,
            t.atoms.bg_contrast_25,
            a.p_md,
            a.rounded_md,
          ]}>
          <Text style={[pal.text, a.text_md]}>
            Your plan renews on {formatDateTime(data?.renewDate)}
          </Text>
        </View>

        <View style={[a.flex, a.flex_row, a.justify_end, a.gap_sm]}>
          <Button
            label={_(msg`Explore`)}
            onPress={closeModal}
            size="small"
            variant="solid"
            color="secondary"
            style={[a.mt_sm, {width: 120}]}>
            <ButtonText>
              <Trans context="action">Manage</Trans>
            </ButtonText>
          </Button>

          <Button
            label={_(msg`Explore`)}
            onPress={() => {
              closeModal()
              navigation.navigate('Home')
            }}
            size="small"
            variant="solid"
            color="primary"
            style={[a.mt_sm, {width: 120}]}>
            <ButtonText>
              <Trans context="action">Explore</Trans>
            </ButtonText>
          </Button>
        </View>
      </ScrollView>
    </SafeAreaView>
  )
}
