import {AUTH_SERVER_URL_BY_ENV, communityPrefix} from '../rep-social-env'

export interface UserInfo {
  handle: string
  role: null | 'Silver' | 'Gold' | 'SysAdmin' | 'Non'
}

export async function getUserInfo(userId: string): Promise<UserInfo | null> {
  if (!userId) return null

  const res = await fetch(
    `${AUTH_SERVER_URL_BY_ENV[communityPrefix]}/auth/rsky/user-info?handle=${userId}`,
    {
      method: 'GET',
      headers: {'Content-Type': 'application/json'},
    },
  )

  if (!res.ok) {
    const data = await res.json().catch(() => null)
    if (res.status === 404 || data?.message === 'User does not exist')
      return null
    const text = await res.text().catch(() => '')
    throw new Error(`getUserInfo failed: ${res.status} ${text}`)
  }

  const data = (await res.json())?.data as UserInfo
  return data
}

export async function verifyCycuridOnBackend(params: {
  handle: string
  sessionId: string
}): Promise<UserInfo> {
  const res = await fetch(
    `${AUTH_SERVER_URL_BY_ENV[communityPrefix]}/auth/rsky/verify-cycurid`,
    {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify(params),
    },
  )
  if (!res.ok) {
    const text = await res.text().catch(() => '')
    throw new Error(`verifyCycuridOnBackend failed: ${res.status} ${text}`)
  }
  return (await res.json()).data as UserInfo
}

export async function setUserRole(params: {
  did: string
  role: 'Silver' | 'Gold' | 'Non' | 'SysAdmin'
  token: string
}) {
  const res = await fetch(
    `${AUTH_SERVER_URL_BY_ENV[communityPrefix]}/auth/rsky/set-role`,
    {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({
        token: params.token,
        targetHandles: [params.did],
        role: params.role,
      }),
    },
  )

  if (!res.ok) {
    const data = await res.json().catch(() => null)
    if (res.status === 404 || data?.message === 'User does not exist')
      return null
    const text = await res.text().catch(() => '')
    throw new Error(`getUserInfo failed: ${res.status} ${text}`)
  }

  const data = (await res.json())?.data
  return data
}

export function isStandardRole(role: any) {
  return !role || role == 'Non'
}

export function isPremiumRole(role: any) {
  return role === 'Gold' || role === 'SysAdmin'
}

export function isSilverRole(role: any) {
  return role === 'Silver'
}
