'use client'
import {type ReactNode} from 'react'
import {createContext, useCallback, useContext, useEffect, useRef} from 'react'
import {repSocialEmbedded, repSocialExtension} from '@fluxion-labs/rep-social'
import type React from 'react'
import io, {type Socket} from 'socket.io-client'

import {useModalControls} from '../modals'
import {
  type CallInvitationData,
  type CallType,
  type CreateRoomPayload,
  RoomEvent,
} from './types'

const SOCKET_URL =
  process.env.NEXT_PUBLIC_VIDEO_CALL_SOCKET_URL ||
  'https://dev-indexer.video-sdk.dlinked.org/room'
const VIDEO_CALL_URL =
  process.env.NEXT_PUBLIC_VIDEO_CALL_URL ||
  'https://video-call-sdk-ui.vercel.app/room'

export type VideoUser = {
  id: string
  avatar?: string
  displayName?: string
}

export type VideoModalData = CallInvitationData & {
  isVideoCall: boolean
  caller: VideoUser
  target: VideoUser
}

export type VideoModalControls = {
  accept: () => void
  reject: () => void
}

export type VideoMessageProps = {
  message: string
  type?: 'info' | 'warning' | 'error'
}

type VideoCallContextType = {
  createRoom: (payload: CreateRoomPayload) => void
  joinRoom: (roomId: string) => void
  rejectCall: (roomId: string) => void
}

const VideoCallContext = createContext<VideoCallContextType | undefined>(
  undefined,
)

export const VideoCallProvider: React.FC<{
  userId: string | undefined
  children: ReactNode
  getUser: (id: string) => Promise<VideoUser>

  showMessage: (msg: VideoMessageProps) => void
}> = ({children, userId, getUser, showMessage}) => {
  const socketRef = useRef<Socket | null>(null)
  const me = useRef<VideoUser | undefined>()
  const isCaller = useRef<boolean>(false)
  const isJoined = useRef<boolean>(false)
  const {openModal, closeModal} = useModalControls()

  useEffect(() => {
    if (!userId) return
    if (repSocialEmbedded.isMobileEmbedded) return

    const socket = io(SOCKET_URL, {
      query: {userId, website: 'SOCIAL'},
      forceNew: true,
    })

    async function init(userId: string) {
      socketRef.current = socket

      me.current = await getUser(userId)
      const errorEvents = [
        RoomEvent.USER_ALREADY_IN_ROOM,
        RoomEvent.USER_UNAVAILABLE,
        RoomEvent.YOU_ALREADY_IN_ROOM,
        RoomEvent.USER_NOT_ONLINE,
      ]

      const messages: Partial<Record<RoomEvent, string>> = {
        [RoomEvent.USER_ALREADY_IN_ROOM]: 'User is already in call',
        [RoomEvent.USER_UNAVAILABLE]: 'User is already in call',
        [RoomEvent.YOU_ALREADY_IN_ROOM]: 'You are already in another call',
        [RoomEvent.USER_NOT_ONLINE]: 'User is not online',
      }

      errorEvents.forEach(evt =>
        socket.on(evt, () => {
          isCaller.current = false
          isJoined.current = false
          showMessage({message: messages[evt] ?? ''})
        }),
      )
      socket.on(RoomEvent.CALL_INVITATION, async (data: CallInvitationData) => {
        isCaller.current = false
        isJoined.current = false
        const isVideoCall = Boolean(data.roomId?.startsWith('video-'))
        const [, encodeCallerId, encodeTargetId] = data.roomId.split('-')
        const [caller, target] = await Promise.all([
          getUser(decodeURIComponent(encodeCallerId)),
          getUser(decodeURIComponent(encodeTargetId)),
        ])
        me.current &&
          openModal({
            name: 'call',
            data: {
              ...data,
              isVideoCall,
              caller,
              target,
            },
          })
      })

      const terminateEvents = [
        RoomEvent.CALL_TIMEOUT,
        RoomEvent.USER_DISCONNECTED,
        RoomEvent.USER_LEAVE_ROOM,
        RoomEvent.CALL_CANCELLED,
      ]

      terminateEvents.forEach(evt =>
        socket.on(evt, () => {
          closeModal()
          isCaller.current = false
          isJoined.current = false
        }),
      )

      socket.on(RoomEvent.ROOM_CREATED, ({roomId}) => {
        if (isCaller.current) {
          socket.emit(RoomEvent.JOIN_ROOM, {roomId})
        }
      })

      socket.on(
        RoomEvent.USER_JOINED_ROOM,
        async ({
          roomId,
          users,
          callType,
        }: {
          userId: string
          roomId: string
          isCaller: boolean
          callType: CallType
          users: {
            userId: string
            socket: {
              socketId: string
              website: 'SOCIAL' | 'VIDEO_CALL'
            }[]
            peerId?: string
          }[]
        }) => {
          const isInCallRoom = users.some(u => u.userId === userId && !u.peerId)
          const [, encodeCallerId, encodeTargetId] = roomId.split('-')
          const callerId = decodeURIComponent(encodeCallerId)
          const targetId = decodeURIComponent(encodeTargetId)
          const partnerId = me.current?.id === callerId ? targetId : callerId

          if (isInCallRoom && partnerId && me.current && !isJoined.current) {
            console.log('USER_JOINED_ROOM', roomId, users, callType)

            const target = await getUser(partnerId)
            const url = new URL(`${VIDEO_CALL_URL}/${roomId}`)
            const params = url.searchParams

            params.set('userId', me.current.id)
            params.set('avatar', me.current.avatar || '')
            params.set('name', me.current.displayName || me.current.id)
            params.set('targetAvatar', target.avatar || '')
            params.set('targetName', target.displayName || target.id)
            params.set('siteType', 'rsky')
            params.set('callType', String(callType))

            if (repSocialEmbedded.isMobileEmbedded) {
              window.location.href = url.toString()
              isJoined.current = true
              return
            }

            if (repSocialExtension.isChromeExtension) {
              repSocialExtension.openNewTab({url: url.toString()})
              isJoined.current = true
              return
            }

            window.open(url.toString(), '_blank')
            isJoined.current = true
          }
        },
      )
    }

    init(userId)

    return () => {
      socket.removeAllListeners()
      socket.disconnect()
      socketRef.current = null
      isCaller.current = false
      isJoined.current = false
    }
  }, [closeModal, getUser, openModal, showMessage, userId])

  const createRoom = useCallback((payload: CreateRoomPayload) => {
    isCaller.current = true
    socketRef.current?.emit(RoomEvent.CREATE_ROOM, payload)
  }, [])

  const joinRoom = useCallback((roomId: string) => {
    socketRef.current?.emit(RoomEvent.JOIN_ROOM, {roomId})
  }, [])

  const rejectCall = useCallback((roomId: string) => {
    socketRef.current?.emit(RoomEvent.REJECT_CALL, {roomId})
  }, [])

  return (
    <>
      <VideoCallContext.Provider value={{createRoom, joinRoom, rejectCall}}>
        {children}
      </VideoCallContext.Provider>
    </>
  )
}

export const useVideoCall = (): VideoCallContextType => {
  const context = useContext(VideoCallContext)
  if (!context)
    throw new Error('useVideoCall must be used within VideoCallProvider')
  return context
}
