export async function getRskyInfo(): Promise<RskyInfo> {
  const res = await fetch(`${SERVER_URL_BY_ENV[communityPrefix]}/app/rsky-info`)

  if (!res.ok) {
    console.error('minFollowers fetch failed')
    return {
      minFollowersCount: MIN_FOLLOWERS_FALLBACK,
      whiteDidlist: [],
    }
  }

  const json = await res.json()

  return {
    minFollowersCount: Number(json?.data?.minFollowers ?? json),
    whiteDidlist: json?.data?.whitelistDIDs || [],
  }
}

export interface RskyInfo {
  minFollowersCount: number
  whiteDidlist: string[]
}
