import * as Sentry from '@sentry/browser'

import {communityPrefix, SERVER_URL_BY_ENV} from '../rep-social-env'

export interface ServerResponse<T> {
  success: boolean
  data: T
}

export interface UserLicense {
  activeNode: number
  isGoldMember: boolean
  isNodeOperator: boolean
  operatorAddress: string
  totalNode: number
}

export enum PaymentType {
  PayForNode = 'PayForNode',
  SubcribeGoldMembership = 'SubcribeGoldMembership',
}

export enum PaymentMethod {
  Crypto = 'Crypto',
  Stripe = 'Stripe',
}

export interface Transaction {
  _id: string
  createdAt: string
  paymentId: string
  userId: string
  galaAddress: string
  amount: number
  currency: string
  createdTs: number
  type: string
  __v: number
  paymentType?: string
  renewDate?: string
}

export interface PaymentInfoItem {
  amount: number
  createdAt: string
  customerId: string
  expiresAt: number
  isRepSky: boolean
  renewDate: string
  status: 'active' | 'canceled'
  subscriptionId: string
  type: 'SubcribeGoldMembership'
  userId: string
}

const API_BASE = SERVER_URL_BY_ENV[communityPrefix]

async function apiFetch<T = any>(
  path: string,
  init?: RequestInit & {parseText?: boolean},
): Promise<T> {
  try {
    const res = await fetch(`${API_BASE}${path}`, {
      method: 'GET',
      ...init,
      headers: {
        'Content-Type': 'application/json',
        ...(init?.headers ?? {}),
      },
    })

    if (!res.ok) {
      // try to surface API error message
      let detail: unknown
      try {
        detail = await res.json()
      } catch {
        detail = await res.text().catch(() => undefined)
      }
      const err = new Error(
        `HTTP ${res.status} ${res.statusText}${
          detail
            ? ` – ${
                typeof detail === 'string' ? detail : JSON.stringify(detail)
              }`
            : ''
        }`,
      )
      throw err
    }

    if ((init as any)?.parseText) {
      return (await res.text()) as T
    }
    return (await res.json()) as T
  } catch (error) {
    Sentry.captureException(error)
    throw error
  }
}

export async function getUserLicense(): Promise<UserLicense | false> {
  try {
    return await apiFetch<UserLicense>('/rep-node/get-user-license')
  } catch (error) {
    console.error('Cannot get user license', error)
    return false
  }
}

