export async function submitTransferTxn(
  txnHash: string,
  type: string,
  payForNode: string,
): Promise<any | false> {
  try {
    return await apiFetch('/rep-node/submit-transfer-txn', {
      method: 'POST',
      body: JSON.stringify({txnHash, type, payForNode}),
    })
  } catch (e) {
    console.error('Cannot submit transfer', e)
    return false
  }
}

export async function registerGala(
  galaAddress: string,
): Promise<any | {error: string; success: false} | false> {
  try {
    return await apiFetch('/rep-node/register', {
      method: 'POST',
      body: JSON.stringify({galaAddress}),
    })
  } catch (e: any) {
    // try to map API error message to the custom response
    const message: string | undefined =
      e?.message &&
      (() => {
        try {
          const m = e.message.match(/"message"\s*:\s*"([^"]+)"/)
          return m?.[1]
        } catch {
          return undefined
        }
      })()

    if (message === 'Node operator already exists') {
      return {
        error: 'This Address is already in use. Please try a different one.',
        success: false as const,
      }
    }

    console.log('Cannot register node', e)
    return false
  }
}

export async function createCheckoutSession(params: {
  userId?: string
  quantity?: number
  paymentType: PaymentType
  galaAddress?: string
  successRedirectUrl: string
  isRepSky: boolean
}) {
  return apiFetch<ServerResponse<{url: string}>>(
    '/rep-node/create-checkout-session',
    {
      method: 'POST',
      body: JSON.stringify({
        quantity: params.quantity || 1,
        galaAddress: params.galaAddress,
        type: params.paymentType,
        successUrl: params.successRedirectUrl,
        isRepSky: params.isRepSky ?? false,
        userId: params.userId,
      }),
    },
  )
}

