import {useCallback, useEffect, useMemo, useState} from 'react'
import {ActivityIndicator, FlatList, TouchableOpacity, View} from 'react-native'
import {msg, Trans} from '@lingui/macro'
import {useLingui} from '@lingui/react'

import {
  cancelSubscription,
  paymentHistory,
  type PaymentInfoItem,
  PaymentMethod,
  type Transaction,
} from '#/lib/api/gold-member'
import {useUser} from '#/lib/hooks/useUser'
import {formatDateTime} from '#/lib/sharing'
import {useModalControls} from '#/state/modals'
import * as Toast from '#/view/com/util/Toast'
import {atoms as a, useTheme} from '#/alf'
import {Button, ButtonText} from '#/components/Button'
import * as Layout from '#/components/Layout'
import {Text} from '#/components/Typography'

export function PaymentHistory({
  subscription,
  onRefresh,
}: {
  subscription: PaymentInfoItem
  onRefresh: () => void
}) {
  const {_} = useLingui()
  const t = useTheme()
  const {user} = useUser()
  const role = user?.role

  const [items, setItems] = useState<Transaction[]>([])
  const [loading, setLoading] = useState(false)
  const [sortDir, setSortDir] = useState<'ASC' | 'DESC'>('DESC')

  const [page, setPage] = useState(0)
  const pageSize = 10
  const [totalCount, setTotalCount] = useState(0)

  const totalPages = useMemo(
    () => Math.max(1, Math.ceil(totalCount / pageSize)),
    [totalCount],
  )

  const {openModal, closeModal} = useModalControls()

  const onCancelSubscription = useCallback(() => {
    openModal({
      name: 'confirm',
      data: {
        title: _('Cancel Subscription'),
        description: _(
          msg`Are you sure you want to cancel your subscription? You will still have access until the end of the current billing period.`,
        ),
        confirmButtonText: _('Yes, Cancel'),
        cancelButtonText: _('No, Keep Subscription'),
        onConfirm: () => {
          closeModal()
          cancelSubscription(subscription.subscriptionId, subscription.userId)
            .then(() => {
              Toast.show(_('Subscription cancelled successfully.'))
            })
            .catch(error => {
              Toast.show(
                _('Failed to cancel subscription. Please try again later.'),
              )
              console.error('Failed to cancel subscription:', error)
            })
          onRefresh()
        },
      },
    })
  }, [
    _,
    subscription.userId,
    subscription.subscriptionId,
    closeModal,
    openModal,
    onRefresh,
  ])

  const fetchPage = useCallback(
    async (p: number) => {
      setLoading(true)
      try {
        const {data} = await paymentHistory(
          pageSize,
          p, // page index
          sortDir,
          PaymentMethod.Stripe,
          subscription.userId,
        )
        setItems(data.payments ?? [])
        setTotalCount(data.totalCount ?? data.payments?.length ?? 0)
      } catch (e) {
        console.error(e)
        setItems([])
        setTotalCount(0)
      } finally {
        setLoading(false)
      }
    },
    [pageSize, sortDir, subscription.userId],
  )

  // load when sub/sort/page changes
  useEffect(() => {
    fetchPage(page)
  }, [fetchPage, page])

  // reset to page 0 when sort or subscription changes
  useEffect(() => {
    setPage(0)
  }, [sortDir, subscription.userId])

  return (
    <Layout.Center style={[a.p_lg, {marginBottom: 55}]}>
      <View style={[a.flex, a.gap_md, a.mb_xl]}>
        <Text style={[a.text_xl, a.font_bold]}>History</Text>
        <View style={[a.flex, a.flex_row, a.justify_between, a.align_center]}>
          {role === 'Gold' && (
            <Text style={[a.text_md]}>
              {_(
                msg`${
                  subscription.status === 'active'
                    ? 'Renew on'
                    : 'Your subscription will expire on'
                } ${formatDateTime(subscription?.renewDate)}`,
              )}
            </Text>
          )}

          {subscription.status === 'active' && (
            <Button
              size="small"
              color="secondary"
              onPress={onCancelSubscription}
              variant="solid"
              label={_(msg`Cancel Subscription`)}
              style={a.rounded_full}>
              <ButtonText>
                <Trans>Cancel Subscription</Trans>
              </ButtonText>
            </Button>
          )}
        </View>
      </View>

      <View
        style={[
          a.w_full,
          a.rounded_md,
          a.overflow_hidden,
          t.atoms.bg_contrast_25,
        ]}>
        {/* Header row */}
        <View
          style={[
            a.w_full,
            a.flex_row,
            a.align_center,
            a.justify_between,
            a.p_lg,
            a.gap_sm,
            t.atoms.bg_contrast_100,
          ]}>
          <View style={[a.flex_1]}>
            <Text style={[a.text_sm, a.font_bold]}>Payment Method</Text>
          </View>
          <View style={[a.flex_1]}>
            <Text style={[a.text_sm, a.font_bold]}>Amount</Text>
          </View>
          <View style={[a.flex_1, a.flex_row, a.align_center]}>
            <Text style={[a.text_sm, a.font_bold]}>Date</Text>
            <TouchableOpacity
              accessibilityHint="Sort by date"
              style={{marginLeft: 8}}
              onPress={() =>
                setSortDir(prev => (prev === 'DESC' ? 'ASC' : 'DESC'))
              }
              accessibilityLabel="Sort by date">
              <Text style={[a.text_sm]}>{sortDir === 'DESC' ? '↓' : '↑'}</Text>
            </TouchableOpacity>
          </View>
        </View>

        {/* Paged list (no infinite scroll) */}
        <FlatList
          data={items}
          renderItem={renderItem}
          keyExtractor={item => item._id}
          ListEmptyComponent={!loading ? renderEmpty : null}
          ListFooterComponent={
            loading ? <ActivityIndicator style={[a.m_lg]} /> : null
          }
          ListFooterComponentStyle={{paddingVertical: 12}}
          removeClippedSubviews={false}
          initialNumToRender={20}
          windowSize={5}
          style={{width: '100%'}}
        />

        {/* Pager controls */}
        <View
          style={[
            a.flex_row,
            a.align_center,
            a.justify_between,
            a.p_md,
            t.atoms.bg_contrast_25,
          ]}>
          <Button
            size="small"
            variant="outline"
            disabled={loading || page <= 0}
            onPress={() => setPage(p => Math.max(0, p - 1))}
            label="Prev">
            <ButtonText>Prev</ButtonText>
          </Button>

          <Text style={[a.text_sm]}>
            Page {totalPages === 0 ? 0 : page + 1} / {totalPages}
          </Text>

          <Button
            size="small"
            variant="outline"
            disabled={loading || page + 1 >= totalPages}
            onPress={() => setPage(p => p + 1)}
            label="Next">
            <ButtonText>Next</ButtonText>
          </Button>
        </View>
      </View>
    </Layout.Center>
  )
}

// --- keep your renderers, but fix the signature (no "style" param) ---
function renderItem({item}: {item: Transaction}) {
  const formattedAmount = `$${Number(item.amount).toFixed(2)}`
  const formattedDate = formatDateTime(item.createdAt)
  const paymentMethod = item.paymentType || 'Stripe'

  return (
    <View
      style={[
        a.w_full,
        a.flex_row,
        a.align_center,
        a.justify_between,
        a.p_lg,
        a.gap_sm,
      ]}>
      <View style={[a.flex_1]}>
        <Text style={[a.text_sm]}>{paymentMethod}</Text>
      </View>
      <View style={[a.flex_1]}>
        <Text style={[a.text_sm]}>{formattedAmount}</Text>
      </View>
      <View style={[a.flex_1]}>
        <Text style={[a.text_sm]}>{formattedDate}</Text>
      </View>
    </View>
  )
}

function renderEmpty() {
  return (
    <View style={[a.flex_1, a.align_center, a.justify_center, a.p_lg]}>
      <Text style={[a.text_md, a.text_center]}>No payment history found.</Text>
    </View>
  )
}
