import {useState} from 'react'
import {
  ActivityIndicator,
  SafeAreaView,
  StyleSheet,
  TouchableOpacity,
  View,
} from 'react-native'
import {LinearGradient} from 'expo-linear-gradient'
import {msg, Trans} from '@lingui/macro'
import {useLingui} from '@lingui/react'

import {usePalette} from '#/lib/hooks/usePalette'
import {gradients, s} from '#/lib/styles'
import {isAndroid} from '#/platform/detection'
import {useModalControls} from '#/state/modals'
import {Text} from '../util/text/Text'
import {ScrollView} from './util'

export const snapPoints = isAndroid ? ['90%'] : ['55%']

export interface ConfirmModalData {
  title: string
  description: string
  confirmButtonText: string
  cancelButtonText?: string
  onConfirm: () => void
}

export function Component({data}: {data: ConfirmModalData}) {
  const pal = usePalette('default')
  const {_} = useLingui()
  const {closeModal} = useModalControls()
  const [isLoading, setLoading] = useState(false)

  const onConfirm = async () => {
    try {
      setLoading(true)
      await data.onConfirm()
    } finally {
      setLoading(false)
    }
  }

  const onCancel = () => {
    closeModal()
  }
  return (
    <SafeAreaView style={[s.flex1]}>
      <ScrollView style={[pal.view]} keyboardShouldPersistTaps="handled">
        <View style={[styles.titleContainer, pal.view]}>
          <Text type="title-xl" style={[s.textCenter, pal.text]}>
            {data.title}
          </Text>
        </View>

        <Text style={[styles.description, pal.textLight]}>
          {data.description}
        </Text>

        <TouchableOpacity
          style={styles.mt20}
          onPress={onConfirm}
          disabled={isLoading}
          accessibilityRole="button"
          accessibilityLabel={data.confirmButtonText}
          accessibilityHint={data.confirmButtonText}>
          <LinearGradient
            colors={[gradients.blueLight.start, gradients.blueLight.end]}
            start={{x: 0, y: 0}}
            end={{x: 1, y: 1}}
            style={[styles.btn]}>
            {isLoading ? (
              <ActivityIndicator color="#d3d3d3" />
            ) : (
              <Text type="button-lg" style={[s.white, s.bold]}>
                {data.confirmButtonText ?? (
                  <Trans context="action">Confirm</Trans>
                )}
              </Text>
            )}
          </LinearGradient>
        </TouchableOpacity>
        <TouchableOpacity
          style={[styles.btn, s.mt10]}
          onPress={onCancel}
          accessibilityRole="button"
          accessibilityLabel={_(msg`Cancel account deletion`)}
          accessibilityHint=""
          onAccessibilityEscape={onCancel}>
          <Text type="button-lg" style={pal.textLight}>
            {data.cancelButtonText ?? <Trans context="action">Cancel</Trans>}
          </Text>
        </TouchableOpacity>
      </ScrollView>
    </SafeAreaView>
  )
}

const styles = StyleSheet.create({
  titleContainer: {
    display: 'flex',
    flexDirection: 'row',
    justifyContent: 'center',
    flexWrap: 'wrap',
    marginTop: 12,
    marginBottom: 12,
    marginLeft: 20,
    marginRight: 20,
  },
  description: {
    textAlign: 'center',
    paddingHorizontal: 22,
    marginBottom: 10,
  },
  mt20: {
    marginTop: 20,
  },

  btn: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: 32,
    padding: 14,
    marginHorizontal: 20,
  },
})
